using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. Strongly-typed metadata via GetTypeInfo<T>() ---
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// Returns JsonTypeInfo<WeatherForecast> directly – no cast needed.
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got typed metadata for: {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

WeatherForecast? roundTripped = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Round-tripped: {roundTripped}");

// --- 2. Probe without throwing via TryGetTypeInfo() ---
Console.WriteLine();

// Case A: type IS resolvable
if (options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo succeeded for {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo returned false for WeatherForecast");

// Case B: use a resolver that only knows about ONE type,
//         so another type is genuinely unresolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo(typeof(WeatherForecast), out _))
    Console.WriteLine("WeatherForecast IS resolvable on limited resolver");
else
    Console.WriteLine("WeatherForecast is NOT resolvable on limited resolver");

if (limited.TryGetTypeInfo(typeof(string), out _))
    Console.WriteLine("string IS resolvable on limited resolver");
else
    Console.WriteLine("string is NOT resolvable on limited resolver");

// ---- Types ----
public record WeatherForecast(string City, int TempC);

/// A resolver that only serves metadata for <see cref="WeatherForecast"/>.
file sealed class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(WeatherForecast) ? _inner.GetTypeInfo(type, options) : null;
}

